103	func TestValidateHoursOverlap(t *testing.T) {
104		cases := []struct {
105			name    string
106			hours   []WeeklyHour
107			wantErr bool
108		}{
109			{"adjacent same day", []WeeklyHour{
110				{1, "10:00", "12:00"}, {1, "12:00", "14:00"},
111			}, false},
112			{"overlap same day", []WeeklyHour{
113				{1, "10:00", "12:00"}, {1, "11:00", "13:00"},
114			}, true},
115			{"containment", []WeeklyHour{
116				{1, "09:00", "18:00"}, {1, "10:00", "11:00"},
117			}, true},
118			{"different days no overlap", []WeeklyHour{
119				{1, "22:00", "02:00"}, {3, "01:00", "03:00"},
120			}, false},
121			// 需求示例：周一 22:00-02:00 与周二 01:00-03:00 必须拒绝。
122			{"cross midnight into next day", []WeeklyHour{
123				{1, "22:00", "02:00"}, {2, "01:00", "03:00"},
124			}, true},
125			// 跨午夜在次日整点结束，与下一天 02:00 开始的时段相邻，允许。
126			{"cross midnight adjacent to next day", []WeeklyHour{
127				{1, "22:00", "02:00"}, {2, "02:00", "04:00"},
128			}, false},
129			// 周日 22:00-02:00 延续到周一，与周一 01:00 冲突。
130			{"sunday spills into monday", []WeeklyHour{
131				{7, "22:00", "02:00"}, {1, "01:00", "03:00"},
132			}, true},
133			// 周日跨午夜在周一 00:00 结束，与周一时段相邻，允许。
134			{"sunday ends exactly monday midnight", []WeeklyHour{
135				{7, "22:00", "00:00"}, {1, "00:00", "02:00"},
136			}, false},
137			// 同一起点的两个时段也属于相交。
138			{"same start", []WeeklyHour{
139				{3, "08:00", "09:00"}, {3, "08:00", "10:00"},
140			}, true},
141		}
142		for _, tc := range cases {
143			t.Run(tc.name, func(t *testing.T) {
144				err := validateHours(tc.hours)
145				if tc.wantErr && err == nil {
146					t.Fatalf("expected overlap error")
147				}
148				if !tc.wantErr && err != nil {
149					t.Fatalf("unexpected error: %v", err)
150				}
151			})
152		}
153	}
