182	func doJSON(t *testing.T, h http.Handler, method, path string, body any) *httptest.ResponseRecorder {
183		t.Helper()
184		var reader *bytes.Reader
185		if body != nil {
186			raw, err := json.Marshal(body)
187			if err != nil {
188				t.Fatalf("marshal: %v", err)
189			}
190			reader = bytes.NewReader(raw)
191		} else {
192			reader = bytes.NewReader(nil)
193		}
194		req := httptest.NewRequest(method, path, reader)
195		req.Header.Set("Content-Type", "application/json")
196		rec := httptest.NewRecorder()
197		h.ServeHTTP(rec, req)
198		return rec
199	}
