201	func decodeBody(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
202		t.Helper()
203		var out map[string]any
204		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
205			t.Fatalf("response is not JSON object: %q (%v)", rec.Body.String(), err)
206		}
207		return out
208	}
