// writeVenuesFile 直接写入原始记录，绕过新增时的校验，用于模拟已损坏的存量数据。
func writeVenuesFile(t *testing.T, s *store, venues any) string {
	t.Helper()
	raw, err := json.Marshal(venues)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
