// parseJSONInteger 按 JSON 数字的准确十进制文本判断它是否为整数，并返回其
// 精确值。value 必须来自开启了 UseNumber 的 JSON 解码（即 json.Number），
// 这样即使是 9007199254740993 这样超过 float64 安全整数范围、或
// 120.00000000000000001 这样带极小小数的数字，也不会在转换中被悄悄舍入。
//
// 第二类返回值 outOfRange 表示：数字确实是数学意义上的整数（120、120.0、
// 1.2e2 都算），但数值落在 supported 区间之外——调用方据此区分“不是整数”
// 与“整数超出支持范围”两种错误。非 json.Number（字符串、布尔、null、对象等）
// 一律视为不是数字。
func parseJSONInteger(value any, min, max int64) (n int64, isInt bool, outOfRange bool) {
	number, ok := value.(json.Number)
	if !ok {
		return 0, false, false
	}
	mant, exp, ok := decimalNumber(string(number))
	if !ok {
		return 0, false, false
	}
	// 按指数移动小数点，得到该数字精确的定点整数表示；过程中只要出现
	// 小数位就说明它不是整数。
	z := new(big.Int).SetBytes(mant.Bytes())
	if mant.Sign() < 0 {
		z.Neg(z)
	}
	if exp >= 0 {
		z.Mul(z, new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(exp)), nil))
	} else {
		divisor := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-exp)), nil)
		if new(big.Int).Mod(z.Abs(z), divisor).Sign() != 0 {
			return 0, false, false
		}
		z.Quo(z, divisor)
	}
	if !z.IsInt64() || z.Int64() < min || z.Int64() > max {
		return 0, true, true
	}
	return z.Int64(), true, false
}

// decimalNumber 把 JSON 数字文本拆成带符号的整数尾数 m 与十进制指数 e，
// 使 原值 == m * 10^e。不接受 Infinity/NaN（JSON 本身也不允许）。
func decimalNumber(text string) (m *big.Int, e int64, ok bool) {
	s := text
	neg := false
	if len(s) > 0 && (s[0] == '+' || s[0] == '-') {
		neg = s[0] == '-'
		s = s[1:]
	}
	if s == "" {
		return nil, 0, false
	}
	intPart, fracPart, hasExp := s, "", false
	if i := strings.IndexAny(s, "eE"); i >= 0 {
		intPart, fracPart, hasExp = s[:i], s[i+1:], true
	}
	var body string
	switch i := strings.IndexByte(intPart, '.'); {
	case !hasExp && i < 0:
		body = intPart
	case i >= 0:
		whole, frac := intPart[:i], intPart[i+1:]
		if frac == "" {
			return nil, 0, false // 如 "1."，不是合法 JSON 数字
		}
		body = whole + frac
		e = -int64(len(frac))
	default:
		body = intPart
	}
	if body == "" || !isDigits(body) {
		return nil, 0, false
	}
	if hasExp {
		exp, err := strconv.ParseInt(fracPart, 10, 64)
		if err != nil {
			return nil, 0, false
		}
		e += exp
	}
	m, ok = new(big.Int).SetString(body, 10)
	if !ok {
		return nil, 0, false
	}
	if neg {
		m.Neg(m)
	}
	return m, e, true
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// requirePositiveInt 校验表示人数的容量字段：必须是 JSON 数字、按准确数值
// 判断为正整数，且落在支持的整数范围内。任何非正整数（含带小数部分的数字）
// 都返回“必须是正整数”，范围合法但过大/过小返回“超出支持范围”，
// 绝不截断或舍入成相邻整数保存。
func requirePositiveInt(payload map[string]any, field string) (int, error) {
	value, ok := payload[field]
	if !ok || value == nil {
		return 0, missingOrWrong(field, "正整数")
	}
	n, isInt, outOfRange := parseJSONInteger(value, 1, maxVenueCapacity)
	if outOfRange {
		return 0, badRequest("%s 超出支持范围：必须是 1 到 %d 的整数", field, maxVenueCapacity)
	}
	if !isInt || n <= 0 {
		return 0, missingOrWrong(field, "正整数")
	}
	return int(n), nil
}

// requireWeekday 用与容量相同的精确文本解析星期字段，保证只接受 1 到 7 的
// 整数（1.5 这类带小数的值不会被舍入后接受）。
func requireWeekday(value any, i int) (int, error) {
	n, isInt, outOfRange := parseJSONInteger(value, 1, 7)
	if outOfRange {
		return 0, badRequest("weeklyHours[%d].weekday 必须为 1 到 7（周一至周日）", i)
	}
	if !isInt {
		return 0, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
	}
	return int(n), nil
}

