			t.Fatalf("status = %d, want 201, body = %s", rec.Code, rec.Body.String())
		}
		if !strings.Contains(rec.Body.String(), "9007199254740993") {
			t.Fatalf("exponential integer must be stored exactly: %s", rec.Body.String())
		}
	})

